mapper.update:
UPDATE job_posts

    TITLE = #{title},
    RECRUIT_COUNT = #{recruitCount},
    EMPLOYMENT_TYPE = #{employmentType},
    SALARY = #{salary},
    WORK_TIME = #{workTime},
    CAREER = #{career},
    EDUCATION = #{education},
    TECH_STACK = #{techStack},
    APPLICATION_PERIOD = #{applicationPeriod}


        , ATTACH_FILE = #{attachFile}
        , ATTACH_FILE_ORIGIN = #{attachFileOrigin}


WHERE JOB_POSTS_IDX = #{jobPostsIdx}
AND COMPANY_IDX = #{companyIdx}

mapper.delete:
DELETE FROM job_posts
WHERE JOB_POSTS_IDX = #{jobPostsIdx}
AND COMPANY_IDX = #{companyIdx}

mapper.select:
SELECT
ATTACH_FILE        AS attachFile,
ATTACH_FILE_ORIGIN AS attachFileOrigin
FROM JOB_POSTS
WHERE JOB_POSTS_IDX = #{jobPostsIdx}
AND COMPANY_IDX   = #{companyIdx}
